import { type FileSystem, path } from '@servicenow/sdk-build-core'
import { generateFluentIndexes } from '../../src/orchestrator/dependencies/fluent-type-generator'
import type { Project } from '../../src/project'

describe('Index Generation', () => {
    let mockFs: Partial<FileSystem> & { existsSync: jest.Mock }
    let mockProject: Partial<Project>
    let fluentTypeDir: string

    beforeEach(() => {
        fluentTypeDir = '/test/project/@types/servicenow/fluent'

        // Mock filesystem
        mockFs = {
            readdirSync: jest.fn(),
            existsSync: jest.fn(),
            accessSync: jest.fn(), // Used by FileSystem.existsSync
            mkdirSync: jest.fn(),
            writeFileSync: jest.fn(),
            readFileSync: jest.fn().mockReturnValue('export const myExport = {}'),
        }

        // Mock project
        mockProject = {
            getFileSystem: () => mockFs as FileSystem,
            resolvePath: (...paths: string[]) => path.join('/test/project', ...paths),
            getConfig: () => ({ typesDir: '@types/servicenow' }) as any,
            getLogger: () => ({
                info: jest.fn(),
                debug: jest.fn(),
                warn: jest.fn(),
                error: jest.fn(),
            }),
        }
    })

    describe('generateFluentIndexes', () => {
        it('should generate index.ts for new action files', async () => {
            const automationDir = path.join(fluentTypeDir, 'automation')
            const actionDir = path.join(automationDir, 'action')
            const globalDir = path.join(actionDir, 'global')

            // Mock directory structure - readdirSync is called with {withFileTypes: true}
            ;(mockFs.existsSync as jest.Mock).mockImplementation(() => true)
            ;(mockFs.readdirSync as jest.Mock).mockImplementation((dir: string) => {
                if (dir === fluentTypeDir) {
                    return [{ name: 'automation', isDirectory: () => true }]
                }
                if (dir === automationDir) {
                    return [{ name: 'action', isDirectory: () => true }]
                }
                if (dir === actionDir) {
                    return [{ name: 'global', isDirectory: () => true }]
                }
                if (dir === globalDir) {
                    return [{ name: 'myAction.d.now.ts', isDirectory: () => false }]
                }
                return []
            })

            await generateFluentIndexes(mockProject as Project)

            // Verify index files were written
            expect(mockFs.writeFileSync).toHaveBeenCalled()
        })

        it('should handle multiple scopes', async () => {
            const automationDir = path.join(fluentTypeDir, 'automation')
            const actionDir = path.join(automationDir, 'action')
            const globalDir = path.join(actionDir, 'global')
            const customDir = path.join(actionDir, 'x_custom')

            ;(mockFs.existsSync as jest.Mock).mockImplementation(() => true)
            ;(mockFs.readdirSync as jest.Mock).mockImplementation((dir: string) => {
                if (dir === fluentTypeDir) {
                    return [{ name: 'automation', isDirectory: () => true }]
                }
                if (dir === automationDir) {
                    return [{ name: 'action', isDirectory: () => true }]
                }
                if (dir === actionDir) {
                    return [
                        { name: 'global', isDirectory: () => true },
                        { name: 'x_custom', isDirectory: () => true },
                    ]
                }
                if (dir === globalDir) {
                    return [{ name: 'action1.d.now.ts', isDirectory: () => false }]
                }
                if (dir === customDir) {
                    return [{ name: 'action2.d.now.ts', isDirectory: () => false }]
                }
                return []
            })

            await generateFluentIndexes(mockProject as Project)

            // Should create indexes for both scopes
            const writeFileCalls = (mockFs.writeFileSync as jest.Mock).mock.calls
            expect(writeFileCalls.length).toBeGreaterThan(0)
        })

        it('should handle empty directories', async () => {
            ;(mockFs.existsSync as jest.Mock).mockReturnValue(true)
            ;(mockFs.readdirSync as jest.Mock).mockReturnValue([])

            // Should not throw
            await expect(generateFluentIndexes(mockProject as Project)).resolves.not.toThrow()
        })

        it('should NOT create empty index for table with no custom files', async () => {
            ;(mockFs.existsSync as jest.Mock).mockReturnValue(true)
            ;(mockFs.readdirSync as jest.Mock).mockReturnValue([])

            await generateFluentIndexes(mockProject as Project)

            // Should NOT create table directory or index
            const mkdirCalls = (mockFs.mkdirSync as jest.Mock).mock.calls
            const tableDir = mkdirCalls.find((call) => call[0].includes('table'))

            expect(tableDir).toBeUndefined()

            const writeFileCalls = (mockFs.writeFileSync as jest.Mock).mock.calls
            const tableIndexCall = writeFileCalls.find((call) => call[0].includes('table/index.ts'))

            expect(tableIndexCall).toBeUndefined()
        })
    })
})
